const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function voiceSettings(settings,names,enabled){
  const s=settings||{provider:'edge',proVoice:'zh-CN-YunxiNeural',conVoice:'zh-CN-XiaoxiaoNeural',rate:1};
  const voices=names||{'zh-CN-YunxiNeural':'云希 · 男声','zh-CN-XiaoxiaoNeural':'晓晓 · 女声'};
  const options=(value,language='zh')=>Object.entries(voices).filter(([id])=>id.startsWith(language+'-')).map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
  return `<section class="form-card settings-card voice-settings"><h2>语音朗读</h2><p class="hint">Edge 神经语音在线生成，朗读文字发送给微软。也可选系统朗读。</p>${enabled?'':'<p class="notice">新版语音将在服务重启后启用。</p>'}<form id="voice-form"><fieldset ${enabled?'':'disabled'}><div class="form-grid"><label>语音模式<select name="provider"><option value="edge" ${s.provider==='edge'?'selected':''}>Edge 神经语音</option><option value="system" ${s.provider==='system'?'selected':''}>系统朗读</option></select></label><label>语速<select name="rate">${[0.8,0.9,1,1.1,1.2,1.3].map(rate=>`<option value="${rate}" ${rate===s.rate?'selected':''}>${rate} 倍</option>`).join('')}</select></label><label>中文正方<select name="proVoice">${options(s.proVoice)}</select></label><label>中文反方<select name="conVoice">${options(s.conVoice)}</select></label><label>英文正方<select name="enProVoice">${options(s.enProVoice||'en-US-GuyNeural','en')}</select></label><label>英文反方<select name="enConVoice">${options(s.enConVoice||'en-US-JennyNeural','en')}</select></label></div><div class="form-actions"><button class="primary" type="submit">保存语音</button><button class="secondary" type="button" data-voice-preview="pro">试听中文正方</button><button class="secondary" type="button" data-voice-preview="con">试听中文反方</button><button class="secondary" type="button" data-voice-preview="en-pro">试听英文正方</button><button class="secondary" type="button" data-voice-preview="en-con">试听英文反方</button><button class="secondary" type="button" id="stop-preview">停止</button></div><p class="hint">试听使用已保存的设置。</p></fieldset></form></section>`;
}
